def calc(expr: str) -> int | str:
    tokens: list[int | str] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            j = i + 1
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            s = expr[i:j]
            if len(s) <= 4000:
                tokens.append(int(s))
            else:
                val = 0
                for k in range(0, len(s), 4000):
                    chunk = s[k : k + 4000]
                    val = val * (10 ** len(chunk)) + int(chunk)
                tokens.append(val)
            i = j
        else:
            tokens.append(ch)
            i += 1

    idx = 0
    m = len(tokens)

    def parse_primary() -> int | None:
        nonlocal idx
        tok = tokens[idx]
        if tok == "(":
            idx += 1
            val = parse_expr()
            if val is None:
                return None
            idx += 1
            return val
        idx += 1
        return tok  # type: ignore[return-value]

    def parse_unary() -> int | None:
        nonlocal idx
        chain: list[tuple[bool, int]] = []
        while True:
            neg = False
            while idx < m and tokens[idx] == "-":
                neg = not neg
                idx += 1
            base = parse_primary()
            if base is None:
                return None
            chain.append((neg, base))
            if idx >= m or tokens[idx] != "^":
                break
            idx += 1

        c_neg, acc = chain.pop()
        if c_neg:
            acc = -acc
        while chain:
            if acc < 0:
                return None
            c_neg, c_base = chain.pop()
            acc = c_base**acc
            if c_neg:
                acc = -acc
        return acc

    def parse_term() -> int | None:
        nonlocal idx
        val = parse_unary()
        if val is None:
            return None
        while idx < m and tokens[idx] in ("*", "/", "%"):
            op = tokens[idx]
            idx += 1
            rhs = parse_unary()
            if rhs is None:
                return None
            if op == "*":
                val *= rhs
            else:
                if rhs == 0:
                    return None
                q = abs(val) // abs(rhs)
                if (val < 0) ^ (rhs < 0):
                    q = -q
                val = q if op == "/" else val - rhs * q
        return val

    def parse_expr() -> int | None:
        nonlocal idx
        val = parse_term()
        if val is None:
            return None
        while idx < m and tokens[idx] in ("+", "-"):
            op = tokens[idx]
            idx += 1
            rhs = parse_term()
            if rhs is None:
                return None
            if op == "+":
                val += rhs
            else:
                val -= rhs
        return val

    res = parse_expr()
    return "error" if res is None else res
